INSERT INTO public.packages (name,slug,category,description,duration_minutes,total_questions,is_free,is_published)
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kepemilikan saham PT PLN (Persero) sepenuhnya dimiliki oleh...','[{"key": "A", "text": "Masyarakat umum melalui pasar modal nasional."}, {"key": "B", "text": "Gabungan investor swasta dan lembaga asing."}, {"key": "C", "text": "Yayasan dan lembaga pendidikan milik pemerintah."}, {"key": "D", "text": "Pemerintah Republik Indonesia sebagai wakil negara."}]'::jsonb,'D','PT PLN (Persero) merupakan salah satu Badan Usaha Milik Negara (BUMN) yang berbentuk Perseroan Terbatas (Persero). Sesuai ketentuan dalam Undang-Undang Nomor 19 Tahun 2003 tentang BUMN, Persero adalah BUMN yang seluruh atau sebagian besar modalnya dimiliki oleh negara, dan modal tersebut berasal dari kekayaan negara yang dipisahkan. Dalam kasus PLN, seluruh sahamnya dimiliki oleh Pemerintah Republik Indonesia, sehingga statusnya adalah Persero 100% milik negara. Hal ini berarti PLN tidak menjual sahamnya di bursa efek (tidak go public), dan seluruh kebijakan strategisnya tetap dikendalikan oleh pemerintah demi menjalankan fungsi pelayanan publik di bidang ketenagalistrikan nasional.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Landasan hukum utama yang mengatur tentang Badan Usaha Milik Negara di Indonesia adalah...','[{"key": "A", "text": "UU No. 40 Tahun 2007"}, {"key": "B", "text": "UU No. 19 Tahun 2003"}, {"key": "C", "text": "UU No. 30 Tahun 2009"}, {"key": "D", "text": "UU No. 20 Tahun 2001"}]'::jsonb,'B','Undang-Undang Nomor 19 Tahun 2003 tentang BUMN merupakan payung hukum (lex generalis) bagi seluruh BUMN di Indonesia, termasuk PT PLN (Persero). UU ini menjadi fondasi yang mengatur berbagai aspek esensial, mulai dari definisi dan bentuk BUMN (Perum dan Persero), peran dan tanggung jawab organ perusahaan (RUPS, Direksi, Komisaris), tata kelola, hingga restrukturisasi dan privatisasi. Kehadiran UU ini memberikan kepastian hukum dan standardisasi dalam pengelolaan aset negara yang dipisahkan.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah kontrak bisnis pengadaan tiang listrik antara PT PLN (Persero) dengan vendor, para pihak sepakat untuk tunduk pada semua klausul yang tertulis. Asas hukum yang mendasari kekuatan mengikat kontrak tersebut adalah...','[{"key": "A", "text": "Lex specialis derogat legi generali"}, {"key": "B", "text": "Pacta sunt servanda"}, {"key": "C", "text": "Asas kebebasan berkontrak"}, {"key": "D", "text": "Asas itikad baik"}]'::jsonb,'B','Asas pacta sunt servanda adalah jantung dari hukum perjanjian. Asas yang berasal dari hukum Romawi ini, dan diadopsi dalam Pasal 1338 Kitab Undang-Undang Hukum Perdata, berarti "perjanjian mengikat para pihak yang membuatnya". Dalam konteks bisnis PLN, asas ini memberikan kepastian hukum bahwa kontrak pengadaan yang telah disepakati secara sah memiliki kekuatan layaknya undang-undang bagi PLN dan vendornya. Pelanggaran terhadap klausul kontrak akan menimbulkan konsekuensi hukum berupa wanprestasi.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Organ BUMN Persero yang bertanggung jawab penuh atas pengurusan perseroan untuk kepentingan dan tujuan perseroan serta mewakili perseroan, baik di dalam maupun di luar pengadilan adalah...','[{"key": "A", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "B", "text": "Dewan Komisaris"}, {"key": "C", "text": "Menteri BUMN"}, {"key": "D", "text": "Direksi"}]'::jsonb,'D','Direksi merupakan organ perseroan yang memegang peran eksekutif dalam menjalankan roda perusahaan sehari-hari. Direksi bertanggung jawab penuh atas pengurusan perseroan sesuai dengan maksud dan tujuan perusahaan. Wewenang ini mencakup pengambilan keputusan strategis, pengelolaan operasional, dan yang terpenting, mewakili perseroan secara sah dalam melakukan perbuatan hukum dengan pihak ketiga, baik di dalam maupun di luar pengadilan.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PT Indonesia Power dan PT Pembangkitan Jawa-Bali (PJB) merupakan contoh ... dari PT PLN (Persero) yang berfokus pada kegiatan pembangkitan tenaga listrik.','[{"key": "A", "text": "Mitra strategis"}, {"key": "B", "text": "Unit Induk Pembangunan"}, {"key": "C", "text": "Anak perusahaan"}, {"key": "D", "text": "Divisi internal"}]'::jsonb,'C','Pembentukan anak perusahaan adalah strategi korporasi yang lazim dilakukan oleh perusahaan besar seperti PLN untuk menciptakan spesialisasi dan efisiensi. Dengan membentuk entitas hukum terpisah yang fokus pada segmen bisnis tertentu (misalnya pembangkitan, transmisi, atau layanan penunjang), perusahaan induk dapat mengoptimalkan kinerja setiap lini bisnis. PT Indonesia Power dan PJB (kini menjadi PLN Nusantara Power) adalah contoh bagaimana PLN memisahkan unit bisnis pembangkitannya agar lebih fokus dan kompetitif.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewenangan tertinggi dalam struktur organisasi BUMN berbentuk Persero seperti PT PLN (Persero) berada di tangan...','[{"key": "A", "text": "Direktur Utama"}, {"key": "B", "text": "Menteri BUMN"}, {"key": "C", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "D", "text": "Dewan Komisaris"}]'::jsonb,'C','Dalam hierarki organ perseroan terbatas, Rapat Umum Pemegang Saham (RUPS) menempati posisi tertinggi. RUPS adalah wadah bagi pemegang saham untuk mengambil keputusan-keputusan paling strategis yang tidak dapat dilimpahkan kepada Direksi maupun Dewan Komisaris. Mengingat 100% saham PLN dimiliki oleh Negara, maka Menteri BUMN bertindak sebagai RUPS yang memiliki kewenangan penuh untuk mengangkat/memberhentikan Direksi/Komisaris, menyetujui laporan tahunan, dan menetapkan arah kebijakan umum perusahaan.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Undang-Undang yang menjadi dasar hukum utama dalam penyelenggaraan usaha ketenagalistrikan di Indonesia saat ini adalah...','[{"key": "A", "text": "UU No. 15 Tahun 1985"}, {"key": "B", "text": "UU No. 22 Tahun 2001"}, {"key": "C", "text": "UU No. 30 Tahun 2009"}, {"key": "D", "text": "UU No. 21 Tahun 2014"}]'::jsonb,'C','Undang-Undang Nomor 30 Tahun 2009 tentang Ketenagalistrikan merupakan landasan hukum modern yang mengatur seluruh aspek industri listrik di Indonesia. UU ini menggantikan peraturan sebelumnya dan menyesuaikan dengan perkembangan zaman, seperti membuka partisipasi swasta secara lebih terstruktur, mengatur standar keselamatan ketenagalistrikan, serta menjamin hak dan kewajiban antara penyedia dan pengguna tenaga listrik.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah perusahaan swasta ingin membangun pembangkit listrik tenaga surya (PLTS) dan menjual listriknya kepada masyarakat di sebuah kawasan industri. Izin usaha utama yang harus dimiliki oleh perusahaan tersebut adalah...','[{"key": "A", "text": "Izin Usaha Pembangkit Listrik Tenaga Surya (IUPLTS)"}, {"key": "B", "text": "Izin Usaha Penyediaan Tenaga Listrik (IUPTL)"}, {"key": "C", "text": "Izin Prinsip Penanaman Modal Usaha Listrik (IPPMUL)"}, {"key": "D", "text": "Izin Mendirikan Usaha Tenaga Surya (IMUTS)"}]'::jsonb,'B','Izin Usaha Penyediaan Tenaga Listrik (IUPTL) adalah izin fundamental yang secara spesifik diamanatkan oleh UU Ketenagalistrikan. Siapapun, termasuk perusahaan swasta, yang ingin melakukan kegiatan usaha penyediaan listrik untuk kepentingan umum (baik pembangkitan, transmisi, distribusi, maupun penjualan) wajib memiliki izin ini. IUPTL memastikan bahwa setiap pelaku usaha di sektor ini telah memenuhi kualifikasi teknis, finansial, dan administratif yang ditetapkan oleh pemerintah.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses perubahan dari satu bentuk energi ke bentuk energi lainnya, seperti perubahan energi uap menjadi energi listrik di PLTU, disebut sebagai...','[{"key": "A", "text": "Regulasi energi"}, {"key": "B", "text": "Diversifikasi energi"}, {"key": "C", "text": "Konservasi energi"}, {"key": "D", "text": "Konversi energi"}]'::jsonb,'D','Konversi energi adalah istilah teknis yang menggambarkan inti dari proses pembangkitan listrik. Proses ini adalah tentang mengubah energi dari bentuk aslinya (misalnya energi kimia pada batu bara, energi potensial pada air, atau energi panas bumi) melalui serangkaian proses teknologi menjadi bentuk energi akhir yang diinginkan, yaitu energi listrik. Memahami proses konversi ini penting untuk mengetahui efisiensi dan dampak lingkungan dari setiap jenis pembangkit.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penugasan dari pemerintah kepada PT PLN (Persero) untuk menyediakan tenaga listrik bagi kepentingan umum di seluruh wilayah Indonesia dikenal dengan istilah...','[{"key": "A", "text": "Public Service Obligation (PSO)"}, {"key": "B", "text": "Corporate Social Responsibility (CSR)"}, {"key": "C", "text": "Good Corporate Governance (GCG)"}, {"key": "D", "text": "Key Performance Indicator (KPI)"}]'::jsonb,'A','Public Service Obligation (PSO) atau Kewajiban Pelayanan Umum adalah instrumen kebijakan pemerintah untuk memastikan bahwa layanan publik yang esensial, seperti listrik, dapat dinikmati oleh seluruh lapisan masyarakat, termasuk di daerah 3T (terdepan, terpencil, dan tertinggal) yang secara komersial tidak layak. Pemerintah menugaskan PLN untuk menjalankan misi ini, dan sebagai kompensasinya, pemerintah memberikan subsidi atau kompensasi dari APBN untuk menutupi biaya yang timbul.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Berdasarkan UU Ketenagalistrikan, wilayah yang menjadi tanggung jawab pemegang izin usaha penyediaan tenaga listrik untuk menyediakan listrik kepada konsumen disebut...','[{"key": "A", "text": "Daerah Operasi"}, {"key": "B", "text": "Zona Distribusi"}, {"key": "C", "text": "Wilayah Usaha"}, {"key": "D", "text": "Kawasan Pelayanan"}]'::jsonb,'C','"Wilayah Usaha" adalah sebuah konsep yuridis dalam UU Ketenagalistrikan. Ini bukan sekadar pembagian area operasional, melainkan penetapan area geografis oleh pemerintah di mana pemegang izin (seperti PLN atau perusahaan swasta) diberi hak dan sekaligus dibebani kewajiban untuk melayani semua calon konsumen di area tersebut. Penetapan Wilayah Usaha memberikan kepastian bagi investor dan jaminan pelayanan bagi masyarakat.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari adanya regulasi di sektor ketenagalistrikan adalah untuk...','[{"key": "A", "text": "Mengatur batasan dan mekanisme keterlibatan pihak swasta dalam kegiatan penyediaan, distribusi, serta penjualan tenaga listrik secara nasional."}, {"key": "B", "text": "Menjamin ketersediaan, keandalan, keberlanjutan, dan harga yang wajar bagi konsumen."}, {"key": "C", "text": "Meningkatkan efisiensi operasional serta memperbesar keuntungan badan usaha milik negara yang bergerak di bidang energi dan ketenagalistrikan."}, {"key": "D", "text": "Mendorong peningkatan pemanfaatan sumber energi fosil secara maksimal guna memenuhi kebutuhan tenaga listrik jangka pendek."}]'::jsonb,'B','Regulasi di sektor ketenagalistrikan, yang merupakan monopoli alamiah dan menyangkut hajat hidup orang banyak, bertujuan untuk menciptakan keseimbangan. Pemerintah sebagai regulator harus memastikan bahwa listrik tersedia secara cukup dan andal (availability & reliability), dapat diakses oleh semua dengan harga yang wajar (affordability), dan diproduksi dengan cara yang berkelanjutan (sustainability). Regulasi mencegah praktik monopoli yang merugikan dan memastikan sektor ini berjalan untuk kemakmuran rakyat.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebelum memulai pembangunan proyek Pembangkit Listrik Tenaga Air (PLTA) yang berpotensi menimbulkan dampak penting terhadap lingkungan, PT PLN (Persero) wajib menyusun dokumen lingkungan yang disebut...','[{"key": "A", "text": "UKL-UPL (Upaya Pengelolaan Lingkungan dan Upaya Pemantauan Lingkungan)"}, {"key": "B", "text": "SPPL (Surat Pernyataan Kesanggupan Pengelolaan dan Pemantauan Lingkungan Hidup)"}, {"key": "C", "text": "AMDAL (Analisis Mengenai Dampak Lingkungan)"}, {"key": "D", "text": "Laporan Studi Kelayakan Proyek"}]'::jsonb,'C','AMDAL (Analisis Mengenai Dampak Lingkungan) adalah instrumen hukum lingkungan yang bersifat preventif. Sebelum sebuah proyek besar seperti PLTA yang berpotensi mengubah ekosistem secara drastis dimulai, AMDAL menjadi kajian ilmiah yang wajib dilakukan untuk memprediksi, mengevaluasi, dan mencari solusi atas dampak penting yang akan ditimbulkan. Kajian ini mencakup aspek bio-fisik-kimia serta sosial-ekonomi-budaya, dan hasilnya menjadi dasar pertimbangan kelayakan lingkungan suatu proyek.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen AMDAL menjadi dasar untuk penerbitan...','[{"key": "A", "text": "Izin Usaha"}, {"key": "B", "text": "Izin Lingkungan"}, {"key": "C", "text": "Izin Lokasi"}, {"key": "D", "text": "Izin Prinsip"}]'::jsonb,'B','Izin Lingkungan adalah keputusan pejabat yang berwenang yang memberikan persetujuan atas kelayakan lingkungan suatu rencana usaha setelah melalui proses telaah dokumen AMDAL. Dokumen AMDAL sendiri adalah kajiannya, sedangkan Izin Lingkungan adalah ''lampu hijau'' yuridis dari sisi lingkungan. Tanpa Izin Lingkungan yang didasarkan pada AMDAL yang layak, sebuah perusahaan seperti PLN tidak dapat melanjutkan ke proses perizinan usaha atau konstruksi.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika terjadi pencemaran lingkungan akibat operasional sebuah pembangkit listrik, maka pihak yang bertanggung jawab untuk memulihkan kerusakan lingkungan adalah pihak yang menyebabkan pencemaran. Prinsip ini dikenal sebagai...','[{"key": "A", "text": "Prinsip Pembangunan Berkelanjutan"}, {"key": "B", "text": "Prinsip Kehati-hatian Dini (Precautionary Principle)"}, {"key": "C", "text": "Prinsip Pencemar Membayar (Polluter Pays Principle)"}, {"key": "D", "text": "Prinsip Partisipasi Masyarakat"}]'::jsonb,'C','Prinsip Pencemar Membayar (Polluter Pays Principle) adalah salah satu pilar utama dalam hukum lingkungan modern. Prinsip ini menegaskan bahwa biaya yang timbul akibat pencemaran atau kerusakan lingkungan, termasuk biaya pencegahan, penanggulangan, dan pemulihan, harus menjadi beban internal dari pelaku usaha yang menyebabkannya. Ini bertujuan agar pelaku usaha tidak mengeksternalisasi biaya lingkungan kepada masyarakat atau negara.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam pembangunan PLTA, salah satu dampak lingkungan dan sosial yang paling signifikan dan harus dikaji secara mendalam dalam AMDAL adalah...','[{"key": "A", "text": "Peningkatan tingkat kebisingan dan gangguan aktivitas masyarakat di sekitar area proyek selama proses konstruksi berlangsung."}, {"key": "B", "text": "Perubahan bentang alam dan ekosistem sungai serta potensi pemindahan pemukiman penduduk."}, {"key": "C", "text": "Timbulnya polusi udara dan emisi gas dari penggunaan mesin-mesin berat pada tahap pembangunan infrastruktur pembangkit."}, {"key": "D", "text": "Penurunan mutu air tanah serta potensi gangguan pada kestabilan tanah akibat getaran dan aktivitas pembangunan bendungan."}]'::jsonb,'B','Pembangunan PLTA secara inheren melibatkan intervensi masif terhadap lingkungan. Pembuatan bendungan raksasa akan menenggelamkan area yang luas, yang secara permanen mengubah bentang alam dan ekosistem darat maupun perairan. Dampak turunannya yang sangat signifikan adalah dampak sosial, di mana masyarakat yang tinggal di area genangan terpaksa harus direlokasi, yang menimbulkan isu-isu kompleks terkait ganti rugi, mata pencaharian, dan adaptasi sosial-budaya.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pertanggungjawaban negara dalam hukum lingkungan diwujudkan melalui...','[{"key": "A", "text": "Pengambilalihan semua perusahaan yang berpotensi mencemari lingkungan."}, {"key": "B", "text": "Pemberian ganti rugi langsung kepada setiap warga negara."}, {"key": "C", "text": "Pembuatan peraturan perundang-undangan, pengawasan, dan penegakan hukum lingkungan."}, {"key": "D", "text": "Pelarangan total terhadap semua kegiatan industri."}]'::jsonb,'C','Pertanggungjawaban negara dalam perlindungan lingkungan tidak diwujudkan dengan mengambil alih kegiatan ekonomi, melainkan dengan menjalankan fungsinya sebagai regulator. Negara bertanggung jawab untuk menciptakan kerangka hukum yang kuat (undang-undang dan peraturan), membangun institusi pengawasan yang efektif untuk memastikan ketaatan, dan menegakkan hukum secara adil dan tegas (baik melalui sanksi administratif, perdata, maupun pidana) terhadap setiap pelanggaran lingkungan.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewajiban untuk memiliki AMDAL berlaku untuk rencana usaha dan/atau kegiatan yang...','[{"key": "A", "text": "Perusahaan yang memiliki karyawan lebih dari 5000 orang."}, {"key": "B", "text": "Berlokasi di dekat kawasan pemukiman padat penduduk."}, {"key": "C", "text": "Berpotensi menimbulkan dampak penting terhadap lingkungan hidup."}, {"key": "D", "text": "Perusahaan yang memiliki modal di atas 10 miliar Rupiah."}]'::jsonb,'C','Kriteria penentu kewajiban penyusunan AMDAL bukanlah besaran modal, lokasi, atau kewarganegaraan investor, melainkan skala potensi "dampak penting" yang akan ditimbulkan. Pemerintah telah menetapkan daftar jenis-jenis usaha yang dianggap berdampak penting, seperti pembangunan bendungan, pembangkit listrik skala besar, atau pembukaan lahan hutan luas. Jika suatu rencana kegiatan masuk dalam daftar tersebut, maka AMDAL menjadi wajib.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebagai sebuah badan usaha berbentuk Perseroan Terbatas, PT PLN (Persero) wajib membayar pajak atas laba bersih yang diperolehnya. Jenis pajak ini disebut...','[{"key": "A", "text": "Pajak Pertambahan Nilai (PPN)"}, {"key": "B", "text": "Pajak Penghasilan (PPh) Badan"}, {"key": "C", "text": "Pajak Bumi dan Bangunan (PBB)"}, {"key": "D", "text": "Pajak Penerangan Jalan (PPJ)"}]'::jsonb,'B','Sebagai subjek hukum yang berbentuk badan (Perseroan Terbatas), PT PLN (Persero) memiliki kewajiban untuk membayar Pajak Penghasilan (PPh) Badan. Objek pajak ini adalah laba atau penghasilan kena pajak yang diperoleh perusahaan dalam satu tahun buku setelah dikurangi biaya-biaya yang diperkenankan oleh undang-undang perpajakan. PPh Badan merupakan sumber penerimaan negara yang signifikan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pajak yang dipungut oleh PT PLN (Persero) dari pelanggan atas konsumsi listrik dan kemudian disetorkan kepada Pemerintah Daerah adalah...','[{"key": "A", "text": "PPh Pasal 21"}, {"key": "B", "text": "Pajak Restoran"}, {"key": "C", "text": "Pajak Penerangan Jalan (PPJ)"}, {"key": "D", "text": "Pajak Pertambahan Nilai (PPN)"}]'::jsonb,'C','Pajak Penerangan Jalan (PPJ) merupakan jenis pajak daerah (kabupaten/kota) yang dikenakan atas setiap penggunaan tenaga listrik oleh konsumen akhir. Dalam praktiknya, PLN ditunjuk oleh undang-undang sebagai Wajib Pungut (WAPU). Artinya, PLN secara otomatis menambahkan komponen tagihan PPJ pada rekening listrik pelanggan, menagihnya, dan kemudian menyetorkan seluruh hasil pungutan tersebut ke kas pemerintah daerah masing-masing.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kepemilikan saham PT PLN (Persero) sepenuhnya dimiliki oleh...','[{"key": "A", "text": "Masyarakat umum melalui pasar modal nasional."}, {"key": "B", "text": "Gabungan investor swasta dan lembaga asing."}, {"key": "C", "text": "Yayasan dan lembaga pendidikan milik pemerintah."}, {"key": "D", "text": "Pemerintah Republik Indonesia sebagai wakil negara."}]'::jsonb,'D','PT PLN (Persero) merupakan salah satu Badan Usaha Milik Negara (BUMN) yang berbentuk Perseroan Terbatas (Persero). Sesuai ketentuan dalam Undang-Undang Nomor 19 Tahun 2003 tentang BUMN, Persero adalah BUMN yang seluruh atau sebagian besar modalnya dimiliki oleh negara, dan modal tersebut berasal dari kekayaan negara yang dipisahkan. Dalam kasus PLN, seluruh sahamnya dimiliki oleh Pemerintah Republik Indonesia, sehingga statusnya adalah Persero 100% milik negara. Hal ini berarti PLN tidak menjual sahamnya di bursa efek (tidak go public), dan seluruh kebijakan strategisnya tetap dikendalikan oleh pemerintah demi menjalankan fungsi pelayanan publik di bidang ketenagalistrikan nasional.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Landasan hukum utama yang mengatur tentang Badan Usaha Milik Negara di Indonesia adalah...','[{"key": "A", "text": "UU No. 40 Tahun 2007"}, {"key": "B", "text": "UU No. 19 Tahun 2003"}, {"key": "C", "text": "UU No. 30 Tahun 2009"}, {"key": "D", "text": "UU No. 20 Tahun 2001"}]'::jsonb,'B','Undang-Undang Nomor 19 Tahun 2003 tentang BUMN merupakan payung hukum (lex generalis) bagi seluruh BUMN di Indonesia, termasuk PT PLN (Persero). UU ini menjadi fondasi yang mengatur berbagai aspek esensial, mulai dari definisi dan bentuk BUMN (Perum dan Persero), peran dan tanggung jawab organ perusahaan (RUPS, Direksi, Komisaris), tata kelola, hingga restrukturisasi dan privatisasi. Kehadiran UU ini memberikan kepastian hukum dan standardisasi dalam pengelolaan aset negara yang dipisahkan.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah kontrak bisnis pengadaan tiang listrik antara PT PLN (Persero) dengan vendor, para pihak sepakat untuk tunduk pada semua klausul yang tertulis. Asas hukum yang mendasari kekuatan mengikat kontrak tersebut adalah...','[{"key": "A", "text": "Lex specialis derogat legi generali"}, {"key": "B", "text": "Pacta sunt servanda"}, {"key": "C", "text": "Asas kebebasan berkontrak"}, {"key": "D", "text": "Asas itikad baik"}]'::jsonb,'B','Asas pacta sunt servanda adalah jantung dari hukum perjanjian. Asas yang berasal dari hukum Romawi ini, dan diadopsi dalam Pasal 1338 Kitab Undang-Undang Hukum Perdata, berarti "perjanjian mengikat para pihak yang membuatnya". Dalam konteks bisnis PLN, asas ini memberikan kepastian hukum bahwa kontrak pengadaan yang telah disepakati secara sah memiliki kekuatan layaknya undang-undang bagi PLN dan vendornya. Pelanggaran terhadap klausul kontrak akan menimbulkan konsekuensi hukum berupa wanprestasi.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Organ BUMN Persero yang bertanggung jawab penuh atas pengurusan perseroan untuk kepentingan dan tujuan perseroan serta mewakili perseroan, baik di dalam maupun di luar pengadilan adalah...','[{"key": "A", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "B", "text": "Dewan Komisaris"}, {"key": "C", "text": "Menteri BUMN"}, {"key": "D", "text": "Direksi"}]'::jsonb,'D','Direksi merupakan organ perseroan yang memegang peran eksekutif dalam menjalankan roda perusahaan sehari-hari. Direksi bertanggung jawab penuh atas pengurusan perseroan sesuai dengan maksud dan tujuan perusahaan. Wewenang ini mencakup pengambilan keputusan strategis, pengelolaan operasional, dan yang terpenting, mewakili perseroan secara sah dalam melakukan perbuatan hukum dengan pihak ketiga, baik di dalam maupun di luar pengadilan.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PT Indonesia Power dan PT Pembangkitan Jawa-Bali (PJB) merupakan contoh ... dari PT PLN (Persero) yang berfokus pada kegiatan pembangkitan tenaga listrik.','[{"key": "A", "text": "Mitra strategis"}, {"key": "B", "text": "Unit Induk Pembangunan"}, {"key": "C", "text": "Anak perusahaan"}, {"key": "D", "text": "Divisi internal"}]'::jsonb,'C','Pembentukan anak perusahaan adalah strategi korporasi yang lazim dilakukan oleh perusahaan besar seperti PLN untuk menciptakan spesialisasi dan efisiensi. Dengan membentuk entitas hukum terpisah yang fokus pada segmen bisnis tertentu (misalnya pembangkitan, transmisi, atau layanan penunjang), perusahaan induk dapat mengoptimalkan kinerja setiap lini bisnis. PT Indonesia Power dan PJB (kini menjadi PLN Nusantara Power) adalah contoh bagaimana PLN memisahkan unit bisnis pembangkitannya agar lebih fokus dan kompetitif.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewenangan tertinggi dalam struktur organisasi BUMN berbentuk Persero seperti PT PLN (Persero) berada di tangan...','[{"key": "A", "text": "Direktur Utama"}, {"key": "B", "text": "Menteri BUMN"}, {"key": "C", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "D", "text": "Dewan Komisaris"}]'::jsonb,'C','Dalam hierarki organ perseroan terbatas, Rapat Umum Pemegang Saham (RUPS) menempati posisi tertinggi. RUPS adalah wadah bagi pemegang saham untuk mengambil keputusan-keputusan paling strategis yang tidak dapat dilimpahkan kepada Direksi maupun Dewan Komisaris. Mengingat 100% saham PLN dimiliki oleh Negara, maka Menteri BUMN bertindak sebagai RUPS yang memiliki kewenangan penuh untuk mengangkat/memberhentikan Direksi/Komisaris, menyetujui laporan tahunan, dan menetapkan arah kebijakan umum perusahaan.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Undang-Undang yang menjadi dasar hukum utama dalam penyelenggaraan usaha ketenagalistrikan di Indonesia saat ini adalah...','[{"key": "A", "text": "UU No. 15 Tahun 1985"}, {"key": "B", "text": "UU No. 22 Tahun 2001"}, {"key": "C", "text": "UU No. 30 Tahun 2009"}, {"key": "D", "text": "UU No. 21 Tahun 2014"}]'::jsonb,'C','Undang-Undang Nomor 30 Tahun 2009 tentang Ketenagalistrikan merupakan landasan hukum modern yang mengatur seluruh aspek industri listrik di Indonesia. UU ini menggantikan peraturan sebelumnya dan menyesuaikan dengan perkembangan zaman, seperti membuka partisipasi swasta secara lebih terstruktur, mengatur standar keselamatan ketenagalistrikan, serta menjamin hak dan kewajiban antara penyedia dan pengguna tenaga listrik.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah perusahaan swasta ingin membangun pembangkit listrik tenaga surya (PLTS) dan menjual listriknya kepada masyarakat di sebuah kawasan industri. Izin usaha utama yang harus dimiliki oleh perusahaan tersebut adalah...','[{"key": "A", "text": "Izin Usaha Pembangkit Listrik Tenaga Surya (IUPLTS)"}, {"key": "B", "text": "Izin Usaha Penyediaan Tenaga Listrik (IUPTL)"}, {"key": "C", "text": "Izin Prinsip Penanaman Modal Usaha Listrik (IPPMUL)"}, {"key": "D", "text": "Izin Mendirikan Usaha Tenaga Surya (IMUTS)"}]'::jsonb,'B','Izin Usaha Penyediaan Tenaga Listrik (IUPTL) adalah izin fundamental yang secara spesifik diamanatkan oleh UU Ketenagalistrikan. Siapapun, termasuk perusahaan swasta, yang ingin melakukan kegiatan usaha penyediaan listrik untuk kepentingan umum (baik pembangkitan, transmisi, distribusi, maupun penjualan) wajib memiliki izin ini. IUPTL memastikan bahwa setiap pelaku usaha di sektor ini telah memenuhi kualifikasi teknis, finansial, dan administratif yang ditetapkan oleh pemerintah.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses perubahan dari satu bentuk energi ke bentuk energi lainnya, seperti perubahan energi uap menjadi energi listrik di PLTU, disebut sebagai...','[{"key": "A", "text": "Regulasi energi"}, {"key": "B", "text": "Diversifikasi energi"}, {"key": "C", "text": "Konservasi energi"}, {"key": "D", "text": "Konversi energi"}]'::jsonb,'D','Konversi energi adalah istilah teknis yang menggambarkan inti dari proses pembangkitan listrik. Proses ini adalah tentang mengubah energi dari bentuk aslinya (misalnya energi kimia pada batu bara, energi potensial pada air, atau energi panas bumi) melalui serangkaian proses teknologi menjadi bentuk energi akhir yang diinginkan, yaitu energi listrik. Memahami proses konversi ini penting untuk mengetahui efisiensi dan dampak lingkungan dari setiap jenis pembangkit.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penugasan dari pemerintah kepada PT PLN (Persero) untuk menyediakan tenaga listrik bagi kepentingan umum di seluruh wilayah Indonesia dikenal dengan istilah...','[{"key": "A", "text": "Public Service Obligation (PSO)"}, {"key": "B", "text": "Corporate Social Responsibility (CSR)"}, {"key": "C", "text": "Good Corporate Governance (GCG)"}, {"key": "D", "text": "Key Performance Indicator (KPI)"}]'::jsonb,'A','Public Service Obligation (PSO) atau Kewajiban Pelayanan Umum adalah instrumen kebijakan pemerintah untuk memastikan bahwa layanan publik yang esensial, seperti listrik, dapat dinikmati oleh seluruh lapisan masyarakat, termasuk di daerah 3T (terdepan, terpencil, dan tertinggal) yang secara komersial tidak layak. Pemerintah menugaskan PLN untuk menjalankan misi ini, dan sebagai kompensasinya, pemerintah memberikan subsidi atau kompensasi dari APBN untuk menutupi biaya yang timbul.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Berdasarkan UU Ketenagalistrikan, wilayah yang menjadi tanggung jawab pemegang izin usaha penyediaan tenaga listrik untuk menyediakan listrik kepada konsumen disebut...','[{"key": "A", "text": "Daerah Operasi"}, {"key": "B", "text": "Zona Distribusi"}, {"key": "C", "text": "Wilayah Usaha"}, {"key": "D", "text": "Kawasan Pelayanan"}]'::jsonb,'C','"Wilayah Usaha" adalah sebuah konsep yuridis dalam UU Ketenagalistrikan. Ini bukan sekadar pembagian area operasional, melainkan penetapan area geografis oleh pemerintah di mana pemegang izin (seperti PLN atau perusahaan swasta) diberi hak dan sekaligus dibebani kewajiban untuk melayani semua calon konsumen di area tersebut. Penetapan Wilayah Usaha memberikan kepastian bagi investor dan jaminan pelayanan bagi masyarakat.','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari adanya regulasi di sektor ketenagalistrikan adalah untuk...','[{"key": "A", "text": "Mengatur batasan dan mekanisme keterlibatan pihak swasta dalam kegiatan penyediaan, distribusi, serta penjualan tenaga listrik secara nasional."}, {"key": "B", "text": "Menjamin ketersediaan, keandalan, keberlanjutan, dan harga yang wajar bagi konsumen."}, {"key": "C", "text": "Meningkatkan efisiensi operasional serta memperbesar keuntungan badan usaha milik negara yang bergerak di bidang energi dan ketenagalistrikan."}, {"key": "D", "text": "Mendorong peningkatan pemanfaatan sumber energi fosil secara maksimal guna memenuhi kebutuhan tenaga listrik jangka pendek."}]'::jsonb,'B','Regulasi di sektor ketenagalistrikan, yang merupakan monopoli alamiah dan menyangkut hajat hidup orang banyak, bertujuan untuk menciptakan keseimbangan. Pemerintah sebagai regulator harus memastikan bahwa listrik tersedia secara cukup dan andal (availability & reliability), dapat diakses oleh semua dengan harga yang wajar (affordability), dan diproduksi dengan cara yang berkelanjutan (sustainability). Regulasi mencegah praktik monopoli yang merugikan dan memastikan sektor ini berjalan untuk kemakmuran rakyat.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebelum memulai pembangunan proyek Pembangkit Listrik Tenaga Air (PLTA) yang berpotensi menimbulkan dampak penting terhadap lingkungan, PT PLN (Persero) wajib menyusun dokumen lingkungan yang disebut...','[{"key": "A", "text": "UKL-UPL (Upaya Pengelolaan Lingkungan dan Upaya Pemantauan Lingkungan)"}, {"key": "B", "text": "SPPL (Surat Pernyataan Kesanggupan Pengelolaan dan Pemantauan Lingkungan Hidup)"}, {"key": "C", "text": "AMDAL (Analisis Mengenai Dampak Lingkungan)"}, {"key": "D", "text": "Laporan Studi Kelayakan Proyek"}]'::jsonb,'C','AMDAL (Analisis Mengenai Dampak Lingkungan) adalah instrumen hukum lingkungan yang bersifat preventif. Sebelum sebuah proyek besar seperti PLTA yang berpotensi mengubah ekosistem secara drastis dimulai, AMDAL menjadi kajian ilmiah yang wajib dilakukan untuk memprediksi, mengevaluasi, dan mencari solusi atas dampak penting yang akan ditimbulkan. Kajian ini mencakup aspek bio-fisik-kimia serta sosial-ekonomi-budaya, dan hasilnya menjadi dasar pertimbangan kelayakan lingkungan suatu proyek.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dokumen AMDAL menjadi dasar untuk penerbitan...','[{"key": "A", "text": "Izin Usaha"}, {"key": "B", "text": "Izin Lingkungan"}, {"key": "C", "text": "Izin Lokasi"}, {"key": "D", "text": "Izin Prinsip"}]'::jsonb,'B','Izin Lingkungan adalah keputusan pejabat yang berwenang yang memberikan persetujuan atas kelayakan lingkungan suatu rencana usaha setelah melalui proses telaah dokumen AMDAL. Dokumen AMDAL sendiri adalah kajiannya, sedangkan Izin Lingkungan adalah ''lampu hijau'' yuridis dari sisi lingkungan. Tanpa Izin Lingkungan yang didasarkan pada AMDAL yang layak, sebuah perusahaan seperti PLN tidak dapat melanjutkan ke proses perizinan usaha atau konstruksi.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika terjadi pencemaran lingkungan akibat operasional sebuah pembangkit listrik, maka pihak yang bertanggung jawab untuk memulihkan kerusakan lingkungan adalah pihak yang menyebabkan pencemaran. Prinsip ini dikenal sebagai...','[{"key": "A", "text": "Prinsip Pembangunan Berkelanjutan"}, {"key": "B", "text": "Prinsip Kehati-hatian Dini (Precautionary Principle)"}, {"key": "C", "text": "Prinsip Pencemar Membayar (Polluter Pays Principle)"}, {"key": "D", "text": "Prinsip Partisipasi Masyarakat"}]'::jsonb,'C','Prinsip Pencemar Membayar (Polluter Pays Principle) adalah salah satu pilar utama dalam hukum lingkungan modern. Prinsip ini menegaskan bahwa biaya yang timbul akibat pencemaran atau kerusakan lingkungan, termasuk biaya pencegahan, penanggulangan, dan pemulihan, harus menjadi beban internal dari pelaku usaha yang menyebabkannya. Ini bertujuan agar pelaku usaha tidak mengeksternalisasi biaya lingkungan kepada masyarakat atau negara.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam pembangunan PLTA, salah satu dampak lingkungan dan sosial yang paling signifikan dan harus dikaji secara mendalam dalam AMDAL adalah...','[{"key": "A", "text": "Peningkatan tingkat kebisingan dan gangguan aktivitas masyarakat di sekitar area proyek selama proses konstruksi berlangsung."}, {"key": "B", "text": "Perubahan bentang alam dan ekosistem sungai serta potensi pemindahan pemukiman penduduk."}, {"key": "C", "text": "Timbulnya polusi udara dan emisi gas dari penggunaan mesin-mesin berat pada tahap pembangunan infrastruktur pembangkit."}, {"key": "D", "text": "Penurunan mutu air tanah serta potensi gangguan pada kestabilan tanah akibat getaran dan aktivitas pembangunan bendungan."}]'::jsonb,'B','Pembangunan PLTA secara inheren melibatkan intervensi masif terhadap lingkungan. Pembuatan bendungan raksasa akan menenggelamkan area yang luas, yang secara permanen mengubah bentang alam dan ekosistem darat maupun perairan. Dampak turunannya yang sangat signifikan adalah dampak sosial, di mana masyarakat yang tinggal di area genangan terpaksa harus direlokasi, yang menimbulkan isu-isu kompleks terkait ganti rugi, mata pencaharian, dan adaptasi sosial-budaya.','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pertanggungjawaban negara dalam hukum lingkungan diwujudkan melalui...','[{"key": "A", "text": "Pengambilalihan semua perusahaan yang berpotensi mencemari lingkungan."}, {"key": "B", "text": "Pemberian ganti rugi langsung kepada setiap warga negara."}, {"key": "C", "text": "Pembuatan peraturan perundang-undangan, pengawasan, dan penegakan hukum lingkungan."}, {"key": "D", "text": "Pelarangan total terhadap semua kegiatan industri."}]'::jsonb,'C','Pertanggungjawaban negara dalam perlindungan lingkungan tidak diwujudkan dengan mengambil alih kegiatan ekonomi, melainkan dengan menjalankan fungsinya sebagai regulator. Negara bertanggung jawab untuk menciptakan kerangka hukum yang kuat (undang-undang dan peraturan), membangun institusi pengawasan yang efektif untuk memastikan ketaatan, dan menegakkan hukum secara adil dan tegas (baik melalui sanksi administratif, perdata, maupun pidana) terhadap setiap pelanggaran lingkungan.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewajiban untuk memiliki AMDAL berlaku untuk rencana usaha dan/atau kegiatan yang...','[{"key": "A", "text": "Perusahaan yang memiliki karyawan lebih dari 5000 orang."}, {"key": "B", "text": "Berlokasi di dekat kawasan pemukiman padat penduduk."}, {"key": "C", "text": "Berpotensi menimbulkan dampak penting terhadap lingkungan hidup."}, {"key": "D", "text": "Perusahaan yang memiliki modal di atas 10 miliar Rupiah."}]'::jsonb,'C','Kriteria penentu kewajiban penyusunan AMDAL bukanlah besaran modal, lokasi, atau kewarganegaraan investor, melainkan skala potensi "dampak penting" yang akan ditimbulkan. Pemerintah telah menetapkan daftar jenis-jenis usaha yang dianggap berdampak penting, seperti pembangunan bendungan, pembangkit listrik skala besar, atau pembukaan lahan hutan luas. Jika suatu rencana kegiatan masuk dalam daftar tersebut, maka AMDAL menjadi wajib.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebagai sebuah badan usaha berbentuk Perseroan Terbatas, PT PLN (Persero) wajib membayar pajak atas laba bersih yang diperolehnya. Jenis pajak ini disebut...','[{"key": "A", "text": "Pajak Pertambahan Nilai (PPN)"}, {"key": "B", "text": "Pajak Penghasilan (PPh) Badan"}, {"key": "C", "text": "Pajak Bumi dan Bangunan (PBB)"}, {"key": "D", "text": "Pajak Penerangan Jalan (PPJ)"}]'::jsonb,'B','Sebagai subjek hukum yang berbentuk badan (Perseroan Terbatas), PT PLN (Persero) memiliki kewajiban untuk membayar Pajak Penghasilan (PPh) Badan. Objek pajak ini adalah laba atau penghasilan kena pajak yang diperoleh perusahaan dalam satu tahun buku setelah dikurangi biaya-biaya yang diperkenankan oleh undang-undang perpajakan. PPh Badan merupakan sumber penerimaan negara yang signifikan.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pajak yang dipungut oleh PT PLN (Persero) dari pelanggan atas konsumsi listrik dan kemudian disetorkan kepada Pemerintah Daerah adalah...','[{"key": "A", "text": "PPh Pasal 21"}, {"key": "B", "text": "Pajak Restoran"}, {"key": "C", "text": "Pajak Penerangan Jalan (PPJ)"}, {"key": "D", "text": "Pajak Pertambahan Nilai (PPN)"}]'::jsonb,'C','Pajak Penerangan Jalan (PPJ) merupakan jenis pajak daerah (kabupaten/kota) yang dikenakan atas setiap penggunaan tenaga listrik oleh konsumen akhir. Dalam praktiknya, PLN ditunjuk oleh undang-undang sebagai Wajib Pungut (WAPU). Artinya, PLN secara otomatis menambahkan komponen tagihan PPJ pada rekening listrik pelanggan, menagihnya, dan kemudian menyetorkan seluruh hasil pungutan tersebut ke kas pemerintah daerah masing-masing.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pemerintah memberikan fasilitas pembebasan bea masuk atas impor mesin pembangkit listrik yang menggunakan energi terbarukan. Kebijakan ini merupakan contoh dari...','[{"key": "A", "text": "Subsidi energi"}, {"key": "B", "text": "Insentif energi/fiskal"}, {"key": "C", "text": "Dana bagi hasil"}, {"key": "D", "text": "Pajak karbon"}]'::jsonb,'B','Insentif energi/fiskal adalah perangkat kebijakan yang digunakan pemerintah untuk mendorong kegiatan ekonomi di sektor-sektor prioritas. Dengan memberikan fasilitas seperti pembebasan bea masuk, pengurangan pajak (tax allowance), atau penangguhan pajak (tax holiday), pemerintah berupaya menurunkan biaya investasi dan meningkatkan kelayakan finansial proyek, khususnya di sektor energi terbarukan yang padat modal, untuk menarik lebih banyak investor.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Objek dari Pajak Pertambahan Nilai (PPN) dalam transaksi ketenagalistrikan adalah...','[{"key": "A", "text": "Penyerahan jasa kena pajak berupa jasa penyediaan tenaga listrik."}, {"key": "B", "text": "Gaji karyawan PLN."}, {"key": "C", "text": "Laba bersih yang diterima oleh PLN."}, {"key": "D", "text": "Tanah dan bangunan yang dimiliki oleh PLN untuk gardu induk."}]'::jsonb,'A','Dalam sistem Pajak Pertambahan Nilai (PPN), yang menjadi objek pajak adalah penyerahan Barang Kena Pajak (BKP) atau Jasa Kena Pajak (JKP). Penyediaan tenaga listrik oleh PLN kepada pelanggan bisnis dan industri besar, serta rumah tangga dengan daya di atas 6.600 VA, dikategorikan sebagai penyerahan JKP. Atas penyerahan jasa inilah PPN dikenakan dan dipungut oleh PLN dari pelanggan tersebut.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama pemerintah memberikan insentif pajak di sektor energi, khususnya energi terbarukan, adalah untuk...','[{"key": "A", "text": "Meningkatkan daya tarik investasi di sektor energi terbarukan."}, {"key": "B", "text": "Mengurangi beban pajak BUMN seperti PLN."}, {"key": "C", "text": "Menurunkan harga listrik secara drastis bagi seluruh pelanggan."}, {"key": "D", "text": "Membatasi penggunaan energi fosil melalui pungutan tambahan."}]'::jsonb,'A','Pengembangan energi terbarukan seringkali dihadapkan pada tantangan keekonomian karena biaya investasi awalnya yang tinggi. Untuk mengakselerasi transisi energi, pemerintah memberikan berbagai insentif pajak. Tujuan utamanya adalah untuk membuat proyek-proyek energi terbarukan menjadi lebih menarik dan kompetitif dari sisi finansial (bankable), sehingga dapat menarik minat investasi baik dari dalam maupun luar negeri.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pengaturan mengenai tarif dan jenis Pajak Daerah dan Retribusi Daerah, termasuk Pajak Penerangan Jalan, diatur dalam...','[{"key": "A", "text": "UU tentang Pajak Daerah dan Retribusi Daerah (PDRD)."}, {"key": "B", "text": "UU tentang Anggaran Pendapatan dan Belanja Negara (APBN)."}, {"key": "C", "text": "UU tentang Ketentuan Umum dan Tata Cara Perpajakan (KUP)."}, {"key": "D", "text": "UU tentang Pajak Penghasilan (PPh)."}]'::jsonb,'A','Sistem perpajakan di Indonesia membagi kewenangan pemungutan pajak antara pemerintah pusat dan pemerintah daerah. UU tentang Pajak Daerah dan Retribusi Daerah (PDRD) adalah landasan hukum yang memberikan wewenang kepada Pemda Provinsi dan Kabupaten/Kota untuk memungut jenis-jenis pajak tertentu, termasuk Pajak Penerangan Jalan. UU ini juga yang menetapkan batas atas tarif yang boleh dikenakan.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika PT PLN (Persero) bekerja sama dengan investor asing dari Jepang untuk membangun sebuah pembangkit listrik, maka kegiatan investasi tersebut tunduk pada peraturan...','[{"key": "A", "text": "UU No. 25 Tahun 2007 tentang Penanaman Modal"}, {"key": "B", "text": "Hukum Dagang Internasional"}, {"key": "C", "text": "Perjanjian Perdagangan Bebas ASEAN"}, {"key": "D", "text": "Konvensi Wina tentang Hubungan Diplomatik"}]'::jsonb,'A','Setiap aktivitas penanaman modal asing (PMA) di Indonesia harus tunduk pada kerangka hukum nasional, yaitu UU Nomor 25 Tahun 2007 tentang Penanaman Modal. Undang-undang ini mengatur berbagai aspek krusial, mulai dari sektor-sektor yang terbuka untuk asing, prosedur perizinan, bentuk badan hukum yang harus digunakan (PT PMA), hingga hak dan kewajiban investor, termasuk hak untuk mendapatkan perlakuan yang adil dan non-diskriminatif.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perjanjian antara Indonesia dan Malaysia untuk membangun interkoneksi jaringan listrik lintas batas negara merupakan contoh dari...','[{"key": "A", "text": "Perjanjian ekstradisi"}, {"key": "B", "text": "Perjanjian energi antarnegara"}, {"key": "C", "text": "Perjanjian perdagangan senjata"}, {"key": "D", "text": "Perjanjian batas wilayah laut"}]'::jsonb,'B','Perjanjian yang dibuat oleh dua negara atau lebih untuk mengatur kerja sama di bidang energi, seperti pembangunan jaringan transmisi listrik lintas batas (interkoneksi), jual beli gas, atau pengembangan sumber energi bersama, diklasifikasikan sebagai perjanjian energi antarnegara. Perjanjian ini merupakan bagian dari hukum internasional publik yang menciptakan hak dan kewajiban bagi negara-negara yang menandatanganinya.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika terjadi sengketa antara investor asing dengan pemerintah Indonesia terkait proyek energi, dan dalam kontrak disepakati penyelesaian melalui lembaga di luar pengadilan nasional, mekanisme yang umum digunakan adalah...','[{"key": "A", "text": "Mediasi di pengadilan negeri"}, {"key": "B", "text": "Gugatan di Mahkamah Internasional"}, {"key": "C", "text": "Arbitrase internasional"}, {"key": "D", "text": "Lobi diplomatik melalui kedutaan besar"}]'::jsonb,'C','Arbitrase internasional adalah mekanisme penyelesaian sengketa alternatif yang sering menjadi pilihan utama dalam kontrak bisnis dan investasi lintas negara. Forum ini dianggap lebih netral, fleksibel, dan cepat dibandingkan litigasi di pengadilan nasional salah satu pihak. Putusan arbitrase (award) bersifat final dan mengikat serta dapat dieksekusi di banyak negara berkat adanya Konvensi New York 1958.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip dalam hukum internasional yang menegaskan bahwa setiap negara memiliki hak penuh untuk mengelola dan memanfaatkan sumber daya alam, termasuk sumber daya energi di dalam wilayahnya, adalah prinsip...','[{"key": "A", "text": "Kedaulatan permanen atas sumber daya alam (Permanent Sovereignty over Natural Resources)"}, {"key": "B", "text": "Prinsip saling menguntungkan antarnegara yang menekankan kerja sama ekonomi dan pembangunan energi secara adil dan seimbang."}, {"key": "C", "text": "Prinsip non-intervensi yang menegaskan larangan campur tangan terhadap kebijakan pengelolaan sumber daya dan urusan domestik suatu negara."}, {"key": "D", "text": "Prinsip perdagangan bebas yang mendorong kelancaran arus barang, jasa, dan investasi energi antarnegara tanpa hambatan tarif maupun kuota."}]'::jsonb,'A','Prinsip Kedaulatan Permanen atas Sumber Daya Alam adalah doktrin fundamental dalam hukum internasional yang menegaskan hak setiap negara untuk secara bebas mengatur, mengelola, dan memanfaatkan semua sumber daya alam yang berada di dalam batas-batas wilayahnya. Prinsip ini menjadi dasar bagi Indonesia untuk membuat undang-undang dan kebijakan di sektor energi dan pertambangan yang bertujuan untuk sebesar-besarnya kemakmuran rakyat.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan dari sebuah Bilateral Investment Treaty (BIT) yang ditandatangani antara dua negara adalah untuk...','[{"key": "A", "text": "Mengatur berbagai ketentuan mengenai tarif impor, ekspor, serta mekanisme perdagangan lintas batas antarnegara guna memperlancar arus barang dan investasi sektor industri."}, {"key": "B", "text": "Mendorong dan melindungi investasi yang dilakukan oleh investor dari satu negara di negara lainnya."}, {"key": "C", "text": "Membangun kesepakatan kerja sama strategis di bidang pertahanan dan keamanan militer untuk memperkuat stabilitas politik dan keamanan kawasan secara timbal balik."}, {"key": "D", "text": "Menetapkan pedoman serta standar internasional yang mengatur perlindungan lingkungan hidup dan pengelolaan sumber daya alam secara global dan berkelanjutan."}]'::jsonb,'B','Bilateral Investment Treaty (BIT) adalah perjanjian internasional antara dua negara yang dirancang khusus untuk mempromosikan dan melindungi investasi. Tujuannya adalah menciptakan iklim investasi yang aman dan dapat diprediksi bagi investor dari negara mitra. BIT biasanya berisi jaminan perlindungan terhadap nasionalisasi tanpa kompensasi, perlakuan yang adil dan setara, serta akses ke mekanisme penyelesaian sengketa internasional.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah perjanjian jual beli gas alam cair (Liquefied Natural Gas - LNG) antara perusahaan Indonesia dengan perusahaan dari Korea Selatan akan diatur oleh...','[{"key": "A", "text": "Hukum pidana internasional"}, {"key": "B", "text": "Kontrak komersial internasional"}, {"key": "C", "text": "Hukum humaniter"}, {"key": "D", "text": "Hukum tata negara kedua negara"}]'::jsonb,'B','Transaksi jual beli komoditas antara dua entitas bisnis, meskipun berasal dari negara yang berbeda, pada dasarnya adalah hubungan hukum keperdataan. Oleh karena itu, hak dan kewajiban para pihak akan diatur secara primer oleh isi dari kontrak komersial internasional yang mereka sepakati. Kontrak ini biasanya juga mencantumkan pilihan hukum (choice of law) yang akan digunakan untuk menginterpretasikan isinya jika terjadi sengketa.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Penetapan Tarif Tenaga Listrik (TTL) untuk golongan pelanggan tertentu oleh pemerintah melalui Peraturan Menteri ESDM merupakan contoh dari produk hukum yang bersifat...','[{"key": "A", "text": "Regeling (pengaturan)"}, {"key": "B", "text": "Beschikking (keputusan)"}, {"key": "C", "text": "Yurisprudensi"}, {"key": "D", "text": "Traktat"}]'::jsonb,'A','Dalam ilmu hukum, produk hukum dibedakan menjadi regeling (pengaturan) dan beschikking (keputusan). Sebuah regeling memiliki ciri-ciri umum, abstrak, dan berlaku terus-menerus. Peraturan Menteri ESDM tentang Tarif Tenaga Listrik (TTL) adalah sebuah regeling karena berlaku bagi semua orang yang memenuhi kriteria sebagai pelanggan golongan tertentu, tidak menunjuk individu spesifik, dan terus berlaku hingga ada perubahan atau pencabutan.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika seorang warga negara merasa dirugikan oleh Surat Keputusan dari pejabat PLN (sebagai badan/pejabat TUN) mengenai penolakan penyambungan baru listrik tanpa alasan yang sah, maka ia dapat mengajukan gugatan ke...','[{"key": "A", "text": "Pengadilan Negeri"}, {"key": "B", "text": "Pengadilan Niaga"}, {"key": "C", "text": "Mahkamah Konstitusi"}, {"key": "D", "text": "Peradilan Tata Usaha Negara (PTUN)"}]'::jsonb,'D','Peradilan Tata Usaha Negara (PTUN) memiliki yurisdiksi untuk mengadili sengketa yang timbul akibat dikeluarkannya Keputusan Tata Usaha Negara (KTUN) oleh badan atau pejabat pemerintah. Surat penolakan sambungan baru dari PLN dapat dianggap sebagai KTUN karena merupakan penetapan tertulis yang bersifat individual, konkret, dan final. Oleh karena itu, warga negara yang merasa haknya dirugikan oleh keputusan tersebut dapat mencari keadilan melalui gugatan di PTUN.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Landasan konstitusional utama bagi negara untuk menguasai cabang-cabang produksi yang penting bagi negara dan menguasai hajat hidup orang banyak, termasuk ketenagalistrikan, adalah...','[{"key": "A", "text": "Pasal 27 UUD 1945"}, {"key": "B", "text": "Pasal 28 UUD 1945"}, {"key": "C", "text": "Pasal 33 UUD 1945"}, {"key": "D", "text": "Pasal 34 UUD 1945"}]'::jsonb,'C','Pasal 33 UUD 1945 merupakan landasan filosofis dan konstitusional bagi sistem perekonomian Indonesia. Ayat (2) dan (3) secara tegas menyatakan bahwa cabang produksi yang penting bagi negara dan menguasai hajat hidup orang banyak, serta kekayaan alam, dikuasai oleh negara dan dipergunakan untuk sebesar-besarnya kemakmuran rakyat. Ketenagalistrikan adalah contoh textbook dari amanat ini, yang menjadi justifikasi utama keberadaan BUMN seperti PLN.','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah Peraturan Pemerintah (PP) tentang Kebijakan Energi Nasional memiliki kedudukan hierarki...','[{"key": "A", "text": "Di atas Undang-Undang (UU)."}, {"key": "B", "text": "Sebagai peraturan pelaksana dari Undang-Undang (UU)."}, {"key": "C", "text": "Setara dengan Peraturan Daerah (Perda)."}, {"key": "D", "text": "Di bawah Peraturan Menteri."}]'::jsonb,'B','Sistem perundang-undangan di Indonesia menganut asas hierarki, di mana peraturan yang lebih rendah tidak boleh bertentangan dengan yang lebih tinggi. Berdasarkan UU No. 12 Tahun 2011, kedudukan Peraturan Pemerintah (PP) berada di bawah Undang-Undang (UU). Fungsi utama PP adalah untuk mengatur lebih lanjut ketentuan dalam UU atau untuk melaksanakan perintah dari UU, sehingga ia berstatus sebagai peraturan pelaksana.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Keputusan Tata Usaha Negara (KTUN) memiliki ciri-ciri...','[{"key": "A", "text": "Tertulis, Konkret, Individual, dan Final."}, {"key": "B", "text": "Abstrak, Umum, dan Berlaku Terus-menerus."}, {"key": "C", "text": "Lisan, Spontan, dan Bersifat Sementara."}, {"key": "D", "text": "Mengikat seluruh warga negara tanpa kecuali."}]'::jsonb,'A','Keputusan Tata Usaha Negara (KTUN) memiliki empat unsur konstitutif yang harus dipenuhi secara kumulatif. Ia harus tertulis (dalam bentuk surat/dokumen), individual (ditujukan pada orang/badan tertentu), konkret (hal yang diputuskan jelas dan tidak abstrak), dan final (menimbulkan akibat hukum secara langsung tanpa memerlukan persetujuan atasan). Memahami ciri-ciri ini penting untuk menentukan apakah suatu tindakan pejabat dapat digugat di PTUN.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Lembaga pemerintah yang memiliki tugas utama untuk mengatur, membina, dan mengawasi sektor ketenagalistrikan di Indonesia adalah...','[{"key": "A", "text": "Kementerian Badan Usaha Milik Negara"}, {"key": "B", "text": "Kementerian Keuangan"}, {"key": "C", "text": "Kementerian Energi dan Sumber Daya Mineral (ESDM)"}, {"key": "D", "text": "Kementerian Perindustrian"}]'::jsonb,'C','Dalam struktur pemerintahan Indonesia, Kementerian Energi dan Sumber Daya Mineral (ESDM) adalah regulator teknis untuk seluruh sektor energi, termasuk ketenagalistrikan. Perannya adalah merumuskan kebijakan energi nasional, menetapkan standar dan norma, melakukan pembinaan teknis, serta mengawasi semua pelaku usaha di sektor ini. Sementara itu, Kementerian BUMN lebih berperan sebagai pembina PLN dari sisi korporasi selaku pemegang saham negara.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pembentukan anak perusahaan oleh BUMN seperti PLN harus mendapatkan persetujuan dari...','[{"key": "A", "text": "Dewan Perwakilan Rakyat (DPR)"}, {"key": "B", "text": "Presiden"}, {"key": "C", "text": "Menteri BUMN selaku RUPS"}, {"key": "D", "text": "Mahkamah Agung"}]'::jsonb,'C','Dalam sebuah BUMN Persero, negara (diwakili oleh Menteri BUMN) bertindak sebagai pemegang saham yang menjalankan fungsi RUPS. Setiap aksi korporasi yang bersifat strategis dan berdampak signifikan terhadap struktur atau keuangan perusahaan, seperti mendirikan anak perusahaan, harus memperoleh persetujuan terlebih dahulu dari RUPS. Ini adalah bagian dari mekanisme kontrol pemegang saham terhadap direksi.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip transparansi dan akuntabilitas dalam pengelolaan BUMN merupakan bagian dari penerapan...','[{"key": "A", "text": "Hukum Pidana Perusahaan"}, {"key": "B", "text": "Asas-asas Umum Pemerintahan yang Baik (AUPB)"}, {"key": "C", "text": "Hukum Acara Perdata"}, {"key": "D", "text": "Kebijakan Fiskal Moneter"}]'::jsonb,'B','Asas-asas Umum Pemerintahan yang Baik (AUPB), seperti asas kepastian hukum, keterbukaan (transparansi), dan akuntabilitas, merupakan prinsip-prinsip etis dan yuridis yang harus menjadi pedoman bagi setiap penyelenggara negara. Prinsip-prinsip ini kemudian diadopsi ke dalam ranah korporasi BUMN melalui penerapan Good Corporate Governance (GCG) untuk memastikan bahwa pengelolaan kekayaan negara dilakukan secara profesional dan dapat dipertanggungjawabkan.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewenangan pemerintah untuk menetapkan harga eceran tertinggi untuk jenis bahan bakar tertentu atau tarif listrik merupakan perwujudan dari fungsi negara sebagai...','[{"key": "A", "text": "Stabilisator dan regulator"}, {"key": "B", "text": "Investor tunggal"}, {"key": "C", "text": "Penegak hukum pidana"}, {"key": "D", "text": "Lembaga yudikatif"}]'::jsonb,'A','Ketika pemerintah melakukan intervensi pasar dengan menetapkan harga eceran tertinggi (HET) atau tarif, ia sedang menjalankan dua fungsi sekaligus. Sebagai regulator, pemerintah membuat aturan main untuk melindungi konsumen dari harga yang eksesif. Sebagai stabilisator, pemerintah berupaya menjaga stabilitas ekonomi dan sosial dengan memastikan harga kebutuhan vital seperti energi tetap terjangkau dan tidak memicu inflasi yang tinggi.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika ada pertentangan antara isi Peraturan Menteri ESDM dengan Undang-Undang Ketenagalistrikan, maka yang harus diutamakan dan berlaku adalah...','[{"key": "A", "text": "Peraturan Menteri karena lebih spesifik."}, {"key": "B", "text": "Keputusan pengadilan terakhir yang relevan."}, {"key": "C", "text": "Kebijakan direksi PLN karena lebih teknis."}, {"key": "D", "text": "Undang-Undang karena hierarkinya lebih tinggi."}]'::jsonb,'D','Prinsip dasar dalam hierarki perundang-undangan adalah Lex superior derogat legi inferiori, yang berarti hukum yang lebih tinggi mengesampingkan hukum yang lebih rendah. Kedudukan Undang-Undang (UU) secara hierarkis lebih tinggi daripada Peraturan Menteri. Oleh karena itu, jika terdapat pertentangan substansi antara keduanya, maka ketentuan dalam Undang-Undanglah yang harus dianggap berlaku dan menjadi acuan.','AKDING',40);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip tata kelola perusahaan yang baik (GCG) yang menekankan pada kesesuaian pengelolaan perusahaan terhadap peraturan perundang-undangan dan nilai-nilai etika adalah...','[{"key": "A", "text": "Transparansi (Transparency)"}, {"key": "B", "text": "Akuntabilitas (Accountability)"}, {"key": "C", "text": "Responsibilitas (Responsibility)"}, {"key": "D", "text": "Independensi (Independency)"}]'::jsonb,'C','Prinsip Responsibilitas (pertanggungjawaban) dalam GCG menekankan bahwa perusahaan harus mematuhi semua peraturan perundang-undangan yang berlaku serta melaksanakan tanggung jawabnya terhadap masyarakat dan lingkungan. Ini mencakup kepatuhan terhadap hukum ketenagakerjaan, peraturan lingkungan, standar keselamatan, dan norma-norma bisnis yang sehat, sebagai wujud dari kesadaran perusahaan akan perannya sebagai bagian dari sistem sosial.','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Aset BUMN, termasuk aset milik PT PLN (Persero), pada dasarnya merupakan...','[{"key": "A", "text": "Barang Milik Negara yang tidak dapat dipindahtangankan."}, {"key": "B", "text": "Kekayaan Negara yang dipisahkan untuk dikelola secara korporasi."}, {"key": "C", "text": "Aset milik pribadi Direksi dan Dewan Komisaris."}, {"key": "D", "text": "Dana APBN yang dialokasikan setiap tahun."}]'::jsonb,'B','Konsep "Kekayaan Negara yang Dipisahkan" adalah kunci untuk memahami status hukum aset BUMN. Artinya, modal yang disetorkan oleh negara kepada PLN telah dipisahkan dari APBN dan statusnya berubah menjadi kekayaan perusahaan. PLN diberi keleluasaan untuk mengelola aset ini secara korporasi (seperti perusahaan swasta) untuk mencapai tujuannya, namun negara tetap menjadi pemegang saham utama yang mengawasi pengelolaannya.','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah kontrak pembangunan Pembangkit Listrik, terdapat klausul yang menyatakan bahwa jika terjadi bencana alam luar biasa yang menghambat proyek, maka kewajiban para pihak dapat ditangguhkan. Klausul ini dikenal sebagai...','[{"key": "A", "text": "Klausul Wanprestasi"}, {"key": "B", "text": "Klausul Arbitrase"}, {"key": "C", "text": "Klausul Force Majeure"}, {"key": "D", "text": "Klausul Eskalasi Harga"}]'::jsonb,'C','Force Majeure atau Keadaan Memaksa adalah klausul standar dalam kontrak-kontrak besar yang bertujuan untuk mengantisipasi kejadian-kejadian luar biasa di luar kendali para pihak (seperti bencana alam, perang, atau kebijakan pemerintah yang mendadak). Jika kondisi force majeure terjadi dan terbukti, maka pihak yang terdampak dapat dibebaskan sementara dari kewajibannya untuk berprestasi tanpa dianggap melakukan wanprestasi.','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan mendasar antara BUMN berbentuk Perusahaan Umum (Perum) dengan Perusahaan Perseroan (Persero) seperti PLN adalah...','[{"key": "A", "text": "Perum dipimpin oleh Direksi, sedangkan Persero oleh Dewan Gubernur."}, {"key": "B", "text": "Seluruh modal Perum dimiliki negara dan tidak terbagi atas saham, sementara modal Persero terbagi atas saham."}, {"key": "C", "text": "Perum bertujuan murni untuk pelayanan publik tanpa mencari keuntungan, sedangkan Persero murni mencari keuntungan."}, {"key": "D", "text": "Perum tunduk pada hukum privat, sedangkan Persero tunduk pada hukum publik."}]'::jsonb,'B','Perbedaan paling fundamental antara Perum dan Persero terletak pada struktur modalnya. Modal Perum sepenuhnya milik negara dan tidak terbagi atas saham, sehingga lebih berorientasi pada pelayanan publik murni. Sebaliknya, modal Persero terbagi atas saham (meskipun pada PLN 100% sahamnya masih dimiliki negara) dan tunduk pada rezim UU Perseroan Terbatas. Perbedaan ini berimplikasi pada tujuan, fleksibilitas operasional, dan mekanisme pengawasannya.','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dewan Komisaris dalam struktur PT PLN (Persero) memiliki fungsi utama untuk...','[{"key": "A", "text": "Menjalankan kegiatan operasional perusahaan sehari-hari dibawah pengawasan dan arahan Komisaris Utama."}, {"key": "B", "text": "Mewakili perusahaan dalam menandatangani kontrak dengan pihak ketiga."}, {"key": "C", "text": "Menetapkan besaran gaji dan bonus untuk seluruh karyawan."}, {"key": "D", "text": "Melakukan pengawasan atas kebijakan pengurusan dan memberikan nasihat kepada Direksi."}]'::jsonb,'D','Dalam sistem dua dewan (two-tier system) yang dianut di Indonesia, Dewan Komisaris (Dewas) memiliki peran pengawasan kolektif terhadap kinerja dan kebijakan Direksi. Fungsi ini mencakup memastikan bahwa Direksi menjalankan perusahaan sesuai Rencana Jangka Panjang Perusahaan (RJPP), prinsip GCG, dan memberikan nasihat strategis. Dewas tidak terlibat dalam pengambilan keputusan operasional sehari-hari.','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tindakan Direksi PT PLN (Persero) untuk menjual sebuah aset vital perusahaan seperti pembangkit listrik utama memerlukan persetujuan dari...','[{"key": "A", "text": "Rapat Umum Pemegang Saham (RUPS)"}, {"key": "B", "text": "Rapat Dewan Komisaris (RDK)"}, {"key": "C", "text": "Papat Dewan Komisaris (RDK) dengan Gubernur setempat"}, {"key": "D", "text": "Pengadilan Niaga"}]'::jsonb,'A','Tindakan korporasi yang bersifat strategis dan berdampak besar, seperti pelepasan (divestasi) aset vital, berada di luar kewenangan rutin Direksi. Keputusan semacam ini harus memperoleh persetujuan dari Rapat Umum Pemegang Saham (RUPS) sebagai organ tertinggi perusahaan. Hal ini untuk memastikan bahwa setiap keputusan strategis telah sejalan dengan kepentingan jangka panjang pemegang saham, yaitu negara.','AKDING',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hak setiap konsumen tenaga listrik untuk mendapatkan pelayanan yang baik dan perbaikan jika pasokan listrik terganggu diatur dalam...','[{"key": "A", "text": "UU Perlindungan Konsumen"}, {"key": "B", "text": "UU Ketenagalistrikan"}, {"key": "C", "text": "UU Perlindungan Konsumen PLN"}, {"key": "D", "text": "Kitab Undang-Undang Hukum Perdata"}]'::jsonb,'B','Meskipun hak konsumen secara umum diatur dalam UU Perlindungan Konsumen, hak dan kewajiban konsumen tenaga listrik secara spesifik dan lebih rinci diatur dalam UU Nomor 30 Tahun 2009 tentang Ketenagalistrikan. UU ini secara khusus mengatur hak konsumen untuk mendapatkan pelayanan yang baik, pasokan listrik yang berkelanjutan, dan ganti rugi jika terjadi pemadaman yang melampaui standar yang ditetapkan.','AKDING',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah perusahaan pengembang kawasan industri yang membangun pembangkit sendiri dan menyalurkan listriknya hanya untuk kebutuhan tenant di dalam kawasannya memerlukan izin yang disebut...','[{"key": "A", "text": "Izin Usaha Penyediaan Tenaga Listrik (IUPTL)"}, {"key": "B", "text": "Izin Operasi (IO)"}, {"key": "C", "text": "Izin Usaha Jasa Penunjang Tenaga Listrik (IUJPTL)"}, {"key": "D", "text": "Sertifikat Laik Operasi (SLO)"}]'::jsonb,'A','Menurut UU Ketenagalistrikan, kegiatan penyediaan tenaga listrik dapat dibedakan untuk kepentingan umum dan kepentingan sendiri. Namun, ketika suatu badan usaha menyediakan listrik untuk pihak lain meskipun dalam satu kawasan terbatas (seperti kawasan industri), kegiatan tersebut sudah dianggap sebagai penyediaan listrik untuk kepentingan umum dan wajib memiliki Izin Usaha Penyediaan Tenaga Listrik (IUPTL) untuk wilayah usaha yang terbatas.','AKDING',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Upaya pemerintah untuk mendorong penggunaan berbagai macam sumber energi untuk pembangkitan listrik (misalnya, gas, batu bara, air, surya) agar tidak bergantung pada satu jenis sumber saja disebut...','[{"key": "A", "text": "Konservasi Energi"}, {"key": "B", "text": "Ketahanan Energi"}, {"key": "C", "text": "Bauran Energi"}, {"key": "D", "text": "Projek Energi Jangka Panjang"}]'::jsonb,'C','Bauran Energi atau Energy Mix adalah kebijakan strategis suatu negara dalam menentukan komposisi atau persentase dari berbagai jenis sumber energi primer (batu bara, gas, minyak, air, panas bumi, surya, dll.) yang digunakan untuk pembangkitan listrik. Tujuannya adalah untuk mencapai ketahanan energi, mengurangi ketergantungan pada satu jenis sumber (terutama impor), dan mendorong transisi ke energi yang lebih bersih.','AKDING',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Standar teknis dan keamanan yang wajib dipenuhi oleh setiap instalasi tenaga listrik sebelum dapat dioperasikan secara komersial dibuktikan dengan kepemilikan...','[{"key": "A", "text": "Izin Mendirikan Bangunan (IMB)"}, {"key": "B", "text": "Sertifikat Laik Operasi (SLO)"}, {"key": "C", "text": "Analisis Mengenai Dampak Lingkungan (AMDAL)"}, {"key": "D", "text": "Izin Usaha Penyediaan Tenaga Listrik (IUPTL)"}]'::jsonb,'B','Sertifikat Laik Operasi (SLO) adalah sertifikat yang dikeluarkan oleh Lembaga Inspeksi Teknik terakreditasi setelah melakukan serangkaian pengujian dan inspeksi. SLO menjadi bukti bahwa suatu instalasi tenaga listrik (mulai dari pembangkit, transmisi, hingga instalasi pelanggan) telah memenuhi standar keamanan, keandalan, dan ramah lingkungan sesuai ketentuan (PUIL/Standar Nasional Indonesia), sehingga aman untuk dioperasikan.','AKDING',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perusahaan swasta yang membangun dan mengoperasikan pembangkit listrik, kemudian menjual listriknya kepada PT PLN (Persero) melalui sebuah Perjanjian Jual Beli Tenaga Listrik (PJBTL), dikenal sebagai...','[{"key": "A", "text": "Independent Power Producer (IPP)"}, {"key": "B", "text": "Konsumen Tegangan Tinggi"}, {"key": "C", "text": "Anak Perusahaan PLN"}, {"key": "D", "text": "Kontraktor EPC (Engineering, Procurement, Construction)"}]'::jsonb,'A','Independent Power Producer (IPP) atau Pengembang Listrik Swasta adalah badan usaha swasta yang berinvestasi membangun dan mengoperasikan pembangkit listrik. Model bisnis utama IPP adalah menjual seluruh energi listrik yang dihasilkannya kepada pembeli tunggal (single buyer), yang di Indonesia perannya dijalankan oleh PT PLN (Persero), melalui sebuah kontrak jangka panjang yang disebut Perjanjian Jual Beli Tenaga Listrik (PJBTL/PPA).','AKDING',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rencana pembangunan ketenagalistrikan secara nasional yang menjadi pedoman bagi seluruh pemangku kepentingan, termasuk PLN dan IPP, disusun oleh pemerintah dalam sebuah dokumen yang disebut...','[{"key": "A", "text": "Rencana Umum Penyediaan Tenaga Listrik (RUPTL)"}, {"key": "B", "text": "Rencana Umum Ketenagalistrikan Nasional (RUKN)"}, {"key": "C", "text": "Rencana Umum Perusahaan Tenaga Listrik (RUPTL)"}, {"key": "D", "text": "Studi Kelayakan Proyek Tahunan Ketenagalistrikan (SKPTK)"}]'::jsonb,'B','Rencana Umum Ketenagalistrikan Nasional (RUKN) adalah dokumen perencanaan tingkat makro yang disusun oleh Pemerintah Pusat (Kementerian ESDM). RUKN memuat kebijakan dan proyeksi kebutuhan serta pasokan listrik secara nasional untuk jangka waktu tertentu. Dokumen ini kemudian menjadi acuan utama bagi PLN dalam menyusun Rencana Usaha Penyediaan Tenaga Listrik (RUPTL) yang lebih detail dan teknis.','AKDING',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk kegiatan pembangunan gardu induk baru yang dampaknya terhadap lingkungan dianggap tidak terlalu signifikan, dokumen lingkungan yang wajib disusun oleh PLN adalah...','[{"key": "A", "text": "AMDAL"}, {"key": "B", "text": "RKL-RPL"}, {"key": "C", "text": "UKL-UPL"}, {"key": "D", "text": "UPP-DAL"}]'::jsonb,'C','Instrumen pengelolaan lingkungan disesuaikan dengan skala dampak proyek. Untuk kegiatan yang potensial dampaknya dianggap tidak signifikan dan teknologinya sudah terstandarisasi, seperti pembangunan gardu induk atau jaringan distribusi, tidak diwajibkan menyusun AMDAL yang kompleks. Sebagai gantinya, diwajibkan menyusun dokumen UKL-UPL yang lebih sederhana, berisi komitmen untuk mengelola dan memantau dampak lingkungan yang mungkin timbul.','AKDING',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip dalam hukum lingkungan yang menyatakan bahwa meskipun bukti ilmiah tentang suatu dampak belum sepenuhnya meyakinkan, namun jika ada ancaman kerusakan yang serius, tindakan pencegahan harus tetap dilakukan, dikenal sebagai...','[{"key": "A", "text": "Prinsip Pencegahan"}, {"key": "B", "text": "Prinsip Kehati-hatian Dini"}, {"key": "C", "text": "Prinsip Pencegahan Dini"}, {"key": "D", "text": "Prinsip Keselamatan"}]'::jsonb,'B','Prinsip Kehati-hatian Dini (Precautionary Principle) menjadi pedoman penting dalam pengambilan keputusan di tengah ketidakpastian ilmiah. Prinsip ini menyatakan bahwa ketiadaan bukti ilmiah yang konklusif tidak boleh dijadikan alasan untuk menunda tindakan pencegahan terhadap ancaman kerusakan lingkungan yang serius atau tidak dapat dipulihkan. Prinsip ini mendorong tindakan preventif daripada reaktif.','AKDING',14);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Limbah sisa pembakaran batu bara dari PLTU, yang dikenal sebagai Fly Ash dan Bottom Ash (FABA), menurut peraturan terbaru dikategorikan sebagai...','[{"key": "A", "text": "Limbah non-B3 yang terdaftar"}, {"key": "B", "text": "Limbah Bahan Berbahaya dan Beracun (B3)"}, {"key": "C", "text": "Sampah domestik"}, {"key": "D", "text": "Limbah radioaktif"}]'::jsonb,'A','Melalui Peraturan Pemerintah No. 22 Tahun 2021, pemerintah mengubah status limbah FABA dari kategori Limbah B3 menjadi Limbah non-B3 yang terdaftar. Perubahan ini bertujuan untuk mendorong pemanfaatan FABA sebagai bahan baku di sektor lain (misalnya konstruksi, jalan, semen) sehingga mengurangi timbunan di landfill dan menciptakan ekonomi sirkular. Meskipun statusnya non-B3, pengelolaannya tetap harus memenuhi standar teknis tertentu.','AKDING',15);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Program penilaian dari Kementerian Lingkungan Hidup dan Kehutanan (KLHK) untuk mengukur tingkat ketaatan dan kinerja lingkungan suatu perusahaan, termasuk pembangkit-pembangkit milik PLN, disebut...','[{"key": "A", "text": "ISO 14001"}, {"key": "B", "text": "PROPER"}, {"key": "C", "text": "PPTKKL"}, {"key": "D", "text": "PROKEKILING"}]'::jsonb,'B','PROPER adalah instrumen pengawasan lingkungan andalan KLHK yang bersifat publik. Melalui PROPER, kinerja lingkungan perusahaan dinilai dan diberi peringkat warna (Emas, Hijau, Biru, Merah, Hitam), di mana Biru adalah peringkat untuk ketaatan minimum. Peringkat ini kemudian diumumkan kepada publik, menciptakan insentif reputasi bagi perusahaan untuk berkinerja lebih baik dari sekadar taat (beyond compliance).','AKDING',16);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pertanggungjawaban mutlak (strict liability) dalam kasus lingkungan berarti bahwa...','[{"key": "A", "text": "Perusahaan hanya bertanggung jawab jika terbukti ada unsur kesengajaan."}, {"key": "B", "text": "Tanggung jawab dapat dialihkan kepada pihak ketiga atau pemerintah."}, {"key": "C", "text": "Unsur kesalahan tidak perlu dibuktikan untuk menuntut ganti rugi."}, {"key": "D", "text": "Ganti rugi hanya dapat diminta setelah ada putusan pidana."}]'::jsonb,'C','Pertanggungjawaban mutlak (strict liability) adalah konsep hukum yang diterapkan pada kegiatan yang berisiko tinggi menimbulkan kerugian, seperti pencemaran limbah B3. Dalam sistem ini, pihak yang dirugikan tidak perlu membuktikan adanya unsur kesalahan (sengaja atau lalai) pada pihak perusahaan. Cukup dengan membuktikan adanya hubungan sebab-akibat antara kegiatan perusahaan dan kerugian yang diderita, maka perusahaan tersebut sudah dapat dimintai pertanggungjawaban.','AKDING',17);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hak masyarakat untuk mendapatkan informasi, memberikan saran, dan terlibat dalam proses pengambilan keputusan terkait proyek kelistrikan yang berpotensi berdampak pada lingkungan mereka dijamin dalam prinsip...','[{"key": "A", "text": "Akuntabilitas Publik"}, {"key": "B", "text": "Kebersamaan"}, {"key": "C", "text": "Partisipasi Publik"}, {"key": "D", "text": "Lingkungan dan Masyarakat"}]'::jsonb,'C','Prinsip Partisipasi Publik menjamin bahwa masyarakat yang berpotensi terkena dampak memiliki hak untuk terlibat dalam proses pengambilan keputusan lingkungan. Hak ini mencakup hak untuk mengakses informasi yang relevan mengenai proyek, hak untuk memberikan masukan dan keberatan, serta hak agar masukan tersebut dipertimbangkan secara serius oleh pemrakarsa proyek dan pemerintah sebelum izin diterbitkan.','AKDING',18);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Atas jasa konsultansi teknik atau jasa manajemen yang diterima oleh PT PLN (Persero) dari perusahaan lain, PLN wajib memotong pajak...','[{"key": "A", "text": "PPh Pasal 21"}, {"key": "B", "text": "PPh Pasal 23"}, {"key": "C", "text": "PPN"}, {"key": "D", "text": "Pajak Penerangan Jalan"}]'::jsonb,'B','Pajak Penghasilan (PPh) Pasal 23 dikenakan atas penghasilan dari modal, penyerahan jasa, atau penyelenggaraan kegiatan selain yang telah dipotong PPh Pasal 21. Ketika PLN membayar imbalan atas jasa teknik, jasa manajemen, atau jasa konsultansi kepada vendor, PLN sebagai pihak pemberi penghasilan wajib memotong PPh Pasal 23 dari pembayaran tersebut dan menyetorkannya ke kas negara.','AKDING',19);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pendapatan Negara Bukan Pajak (PNBP) di sektor ketenagalistrikan dapat berasal dari...','[{"key": "A", "text": "Pajak penghasilan karyawan PLN."}, {"key": "B", "text": "Denda administratif atas keterlambatan pembayaran tagihan listrik."}, {"key": "C", "text": "Biaya penyambungan baru yang dibayar pelanggan."}, {"key": "D", "text": "Biaya perolehan Izin Usaha Penyediaan Tenaga Listrik (IUPTL)."}]'::jsonb,'D','Pendapatan Negara Bukan Pajak (PNBP) adalah seluruh penerimaan pemerintah pusat yang tidak berasal dari perpajakan. Di sektor ESDM, salah satu sumber PNBP adalah pungutan yang dikenakan atas pemberian izin atau lisensi. Biaya yang harus dibayarkan oleh perusahaan untuk memperoleh IUPTL dari pemerintah masuk ke dalam kategori PNBP dan disetorkan ke kas negara.','AKDING',20);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kebijakan pemerintah yang mewajibkan PT PLN (Persero) untuk membeli listrik dari pembangkit energi terbarukan dengan harga tertentu yang lebih tinggi dari biaya produksi PLN, merupakan contoh dari...','[{"key": "A", "text": "Pajak Karbon"}, {"key": "B", "text": "Insentif Non-Fiskal"}, {"key": "C", "text": "Subsidi Langsung"}, {"key": "D", "text": "Kebijakan Feed-in Tariff"}]'::jsonb,'D','Feed-in Tariff adalah salah satu mekanisme insentif yang paling umum digunakan untuk mengakselerasi pengembangan energi terbarukan. Pemerintah menetapkan harga jual listrik premium (di atas harga pasar) yang wajib dibeli oleh perusahaan listrik nasional (PLN) dari pengembang energi terbarukan. Kebijakan ini memberikan kepastian pendapatan jangka panjang bagi investor dan membuat proyek energi terbarukan menjadi lebih layak secara finansial.','AKDING',21);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Bea Meterai dikenakan atas dokumen-dokumen perjanjian yang dibuat oleh PLN, seperti...','[{"key": "A", "text": "Standar Operasional Prosedur (SOP) internal perusahaan."}, {"key": "B", "text": "Dokumen penawaran tender (lelang) yang diajukan oleh vendor kepada perusahaan"}, {"key": "C", "text": "Faktur Pajak (PPN) yang diterbitkan atas tagihan listrik pelanggan"}, {"key": "D", "text": "Perjanjian Jual Beli Tenaga Listrik (PJBTL) dengan nilai di atas batas tertentu."}]'::jsonb,'B','Menurut UU Bea Meterai, dokumen yang bersifat perdata dan digunakan sebagai alat bukti di pengadilan, seperti surat perjanjian, dikenakan Bea Meterai. Sebuah Perjanjian Jual Beli Tenaga Listrik (PJBTL) yang merupakan kontrak bernilai besar dan memuat hak serta kewajiban para pihak, wajib dibubuhi meterai agar memenuhi persyaratan formalitas sebagai alat bukti yang sah.','AKDING',22);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Ketika pemerintah menaikkan tarif Pajak Penerangan Jalan (PPJ), maka yang akan menanggung beban kenaikan tersebut secara langsung adalah...','[{"key": "A", "text": "PT PLN (Persero)"}, {"key": "B", "text": "Pemerintah Pusat"}, {"key": "C", "text": "Perusahaan pemasok batu bara"}, {"key": "D", "text": "Konsumen atau pelanggan listrik"}]'::jsonb,'D','Meskipun PLN yang bertindak sebagai pemungut, Pajak Penerangan Jalan (PPJ) pada hakikatnya adalah pajak atas konsumsi. Beban pajak (tax incidence) pada akhirnya ditanggung oleh pihak yang mengonsumsi barang atau jasa tersebut, yaitu pelanggan listrik. Kenaikan tarif PPJ akan langsung tercermin sebagai kenaikan pada total tagihan rekening listrik bulanan yang harus dibayar oleh konsumen.','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Audit yang dilakukan oleh Badan Pemeriksa Keuangan (BPK) terhadap laporan keuangan PT PLN (Persero), terutama terkait dana subsidi listrik (PSO), bertujuan untuk memastikan...','[{"key": "A", "text": "Perbandingan kenaikan laba perusahaan setiap tahun terhadap pembiayaannya."}, {"key": "B", "text": "Penggunaan dana negara telah sesuai dengan peraturan dan tujuan yang ditetapkan."}, {"key": "C", "text": "Semua pegawai PLN telah membayar PPh Pasal 21."}, {"key": "D", "text": "Tingkat kepuasan pelanggan telah tercapai."}]'::jsonb,'B','Badan Pemeriksa Keuangan (BPK) memiliki wewenang konstitusional untuk memeriksa pengelolaan dan tanggung jawab keuangan negara. Ketika PLN menerima dana PSO dari APBN, dana tersebut berstatus sebagai keuangan negara. Audit BPK bertujuan untuk memastikan bahwa dana tersebut telah digunakan oleh PLN secara akuntabel, transparan, dan tepat sasaran sesuai dengan peraturan perundang-undangan yang berlaku.','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam Perjanjian Jual Beli Tenaga Listrik (PJBTL) antara PLN dengan investor asing, klausul yang mengatur hukum negara mana yang akan digunakan untuk menginterpretasikan isi perjanjian disebut...','[{"key": "A", "text": "Choice of Law"}, {"key": "B", "text": "Choice of Forum"}, {"key": "C", "text": "Force Majeure"}, {"key": "D", "text": "Confidentiality Clause"}]'::jsonb,'A','Dalam kontrak yang melibatkan pihak dari yurisdiksi negara yang berbeda, sangat penting untuk menentukan hukum mana yang akan berlaku jika terjadi sengketa interpretasi. Klausul Choice of Law (Pilihan Hukum) adalah kesepakatan para pihak untuk menundukkan kontrak mereka pada sistem hukum negara tertentu (misalnya, Hukum Indonesia atau Hukum Inggris). Ini memberikan kepastian dan prediktabilitas dalam penyelesaian sengketa.','AKDING',25);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Organisasi internasional antar-pemerintah yang berfokus pada promosi dan pemanfaatan energi terbarukan di seluruh dunia adalah...','[{"key": "A", "text": "OPEC"}, {"key": "B", "text": "IEA"}, {"key": "C", "text": "IREAA"}, {"key": "D", "text": "IRENA"}]'::jsonb,'D','IRENA (International Renewable Energy Agency) adalah organisasi antarpemerintah global yang secara eksklusif didedikasikan untuk menjadi pusat keunggulan dan platform kerja sama internasional dalam bidang energi terbarukan. IRENA mendukung negara-negara dalam transisi energi mereka dengan menyediakan data, analisis kebijakan, dan bantuan teknis.','AKDING',26);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika terjadi sengketa dalam proyek investasi asing dan para pihak memilih menyelesaikannya melalui arbitrase di bawah naungan Bank Dunia, lembaga yang akan memfasilitasinya adalah...','[{"key": "A", "text": "ICSID"}, {"key": "B", "text": "SIAC"}, {"key": "C", "text": "ICC"}, {"key": "D", "text": "BANI"}]'::jsonb,'A','ICSID (International Centre for Settlement of Investment Disputes) adalah lembaga yang merupakan bagian dari Grup Bank Dunia. ICSID didirikan secara khusus untuk menyediakan fasilitas mediasi dan arbitrase dalam penyelesaian sengketa investasi antara negara tuan rumah (host state) dengan investor asing. Banyak perjanjian investasi internasional menunjuk ICSID sebagai forum penyelesaian sengketa.','AKDING',27);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Klausul dalam perjanjian investasi internasional yang menjamin bahwa investor asing akan diperlakukan tidak kurang menguntungkan dibandingkan investor domestik disebut...','[{"key": "A", "text": "Favoured-Nation Treatment (FNT)"}, {"key": "B", "text": "National Treatment (NT)"}, {"key": "C", "text": "Fair and Equitable Treatment (FET)"}, {"key": "D", "text": "Expropriation Clause"}]'::jsonb,'B','Prinsip Perlakuan Nasional (National Treatment) adalah standar perlindungan fundamental dalam perjanjian investasi. Prinsip ini mewajibkan negara tuan rumah untuk memberikan perlakuan kepada investor asing dan investasinya yang tidak kurang menguntungkan (no less favourable) dibandingkan perlakuan yang diberikannya kepada investor domestiknya sendiri dalam keadaan yang serupa.','AKDING',28);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam sebuah kontrak pembangunan pembangkit, seringkali terdapat klausul yang mewajibkan investor asing untuk menggunakan tenaga kerja dan komponen lokal dalam persentase tertentu. Klausul ini bertujuan untuk...','[{"key": "A", "text": "Mendorong terjadinya transfer teknologi dan dampak ekonomi lokal."}, {"key": "B", "text": "Membatasi keuntungan investor asing."}, {"key": "C", "text": "Memenuhi standar lingkungan hidup internasional."}, {"key": "D", "text": "Menghindari pengenaan pajak berganda."}]'::jsonb,'A','Klausul mengenai Tingkat Komponen Dalam Negeri (TKDN) atau kewajiban penggunaan konten lokal bertujuan untuk memastikan bahwa proyek investasi asing memberikan dampak ekonomi berganda (multiplier effect) bagi negara tuan rumah. Dengan mewajibkan penggunaan tenaga kerja, barang, dan jasa lokal, diharapkan terjadi alih pengetahuan dan teknologi, serta tumbuhnya industri pendukung di dalam negeri.','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah putusan arbitrase internasional yang memenangkan gugatan investor asing terhadap Indonesia terkait proyek listrik dapat dieksekusi di Indonesia berdasarkan...','[{"key": "A", "text": "Perintah langsung dari Presiden."}, {"key": "B", "text": "Konvensi New York 1958."}, {"key": "C", "text": "Konvensi Paris 1980."}, {"key": "D", "text": "Konvensi UN 1999."}]'::jsonb,'B','Indonesia telah meratifikasi Konvensi New York 1958, yang merupakan instrumen hukum internasional kunci yang memfasilitasi penegakan putusan arbitrase komersial asing. Berdasarkan konvensi ini, putusan arbitrase yang dijatuhkan di satu negara anggota dapat diakui dan dilaksanakan di negara anggota lainnya, tunduk pada prosedur pendaftaran dan beberapa pengecualian yang sangat terbatas.','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tindakan pemerintah mencabut Izin Usaha Penyediaan Tenaga Listrik (IUPTL) sebuah perusahaan karena melakukan pelanggaran berat merupakan contoh dari penerapan...','[{"key": "A", "text": "Sanksi Pidana"}, {"key": "B", "text": "Sanksi Perdata"}, {"key": "C", "text": "Sanksi Administratif"}, {"key": "D", "text": "Kebijakan Diskresi"}]'::jsonb,'C','Sanksi Administratif adalah tindakan hukuman yang dikenakan oleh lembaga pemerintah terhadap pelanggaran peraturan administrasi, tanpa melalui proses peradilan pidana atau perdata. Contohnya meliputi teguran tertulis, pembekuan kegiatan, hingga yang paling berat adalah pencabutan izin. Tindakan ini bertujuan untuk menegakkan kepatuhan terhadap peraturan yang berlaku.','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Asas pemerintahan yang baik yang menuntut agar setiap keputusan pejabat administrasi negara, termasuk direksi PLN dalam kapasitas publiknya, harus didasarkan pada alasan yang logis dan dapat dipertanggungjawabkan disebut...','[{"key": "A", "text": "Asas Kepastian Hukum"}, {"key": "B", "text": "Asas Keterbukaan"}, {"key": "C", "text": "Asas Proporsionalitas"}, {"key": "D", "text": "Asas Kecermatan dan Motivasi"}]'::jsonb,'D','Asas Kecermatan menuntut pejabat untuk mengumpulkan semua fakta dan informasi yang relevan sebelum membuat keputusan. Asas Motivasi (pemberian alasan) mewajibkan pejabat untuk memberikan justifikasi atau alasan yang jelas, logis, dan memadai di balik keputusannya. Kedua asas ini memastikan bahwa keputusan administrasi tidak dibuat secara sembarangan atau sewenang-wenang.','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hak negara untuk melakukan pengambilalihan (nasionalisasi) perusahaan swasta di sektor strategis seperti kelistrikan demi kepentingan umum, harus disertai dengan...','[{"key": "A", "text": "Persetujuan dari negara asal investor."}, {"key": "B", "text": "Pemberian ganti rugi yang layak sesuai peraturan."}, {"key": "C", "text": "Putusan Mahkamah Internasional."}, {"key": "D", "text": "Referendum nasional."}]'::jsonb,'B','Meskipun negara memiliki hak kedaulatan untuk melakukan nasionalisasi atau pengambilalihan aset demi kepentingan umum, hukum internasional dan UU Penanaman Modal di Indonesia mensyaratkan bahwa tindakan tersebut harus dilakukan sesuai hukum, tidak diskriminatif, dan yang terpenting, disertai dengan pembayaran kompensasi atau ganti rugi yang cepat, memadai, dan efektif (prompt, adequate, and effective compensation).','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Upaya hukum yang dapat ditempuh oleh masyarakat untuk menguji apakah isi dari sebuah Peraturan Menteri ESDM bertentangan dengan Undang-Undang Ketenagalistrikan adalah...','[{"key": "A", "text": "Gugatan Tata Usaha Negara ke PTUN"}, {"key": "B", "text": "Uji Materiil (Judicial Review) ke Mahkamah Agung"}, {"key": "C", "text": "Uji Materiil (Judicial Review) ke Mahkamah Konstitusi"}, {"key": "D", "text": "Laporan ke Ombudsman Republik Indonesia"}]'::jsonb,'B','Sistem hukum di Indonesia membagi kewenangan uji materiil. Mahkamah Konstitusi berwenang menguji UU terhadap UUD 1945. Sementara itu, untuk menguji peraturan di bawah UU (seperti Peraturan Menteri) terhadap UU yang menjadi induknya, kewenangan tersebut diberikan kepada Mahkamah Agung. Proses ini disebut judicial review dan dapat diajukan oleh siapa saja yang merasa haknya dirugikan oleh peraturan tersebut.','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah surat edaran dari Direksi PLN kepada seluruh unit di internal perusahaan yang berisi petunjuk teknis pelaksanaan suatu pekerjaan, secara hukum memiliki kekuatan mengikat sebagai...','[{"key": "A", "text": "Peraturan Perundang-undangan"}, {"key": "B", "text": "Keputusan Tata Usaha Negara (KTUN)"}, {"key": "C", "text": "Peraturan Kebijakan (beleidsregel)"}, {"key": "D", "text": "Yurisprudensi"}]'::jsonb,'C','Surat Edaran internal tidak termasuk dalam hierarki peraturan perundang-undangan yang mengikat keluar. Ia merupakan beleidsregel atau peraturan kebijakan yang hanya memiliki kekuatan mengikat secara internal di dalam suatu organisasi. Fungsinya adalah sebagai pedoman atau petunjuk pelaksanaan bagi para pejabat/pegawai di lingkungan instansi tersebut dalam menjalankan tugasnya.','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Hubungan antara Rencana Umum Ketenagalistrikan Nasional (RUKN) yang disusun pemerintah pusat dengan Rencana Umum Ketenagalistrikan Daerah (RUKD) yang disusun pemerintah daerah adalah...','[{"key": "A", "text": "RUKD dapat bertentangan dengan RUKN."}, {"key": "B", "text": "RUKN harus mengacu dan menyesuaikan diri dengan RUKD."}, {"key": "C", "text": "RUKD merupakan penjabaran dari RUKN dan tidak boleh bertentangan dengannya."}, {"key": "D", "text": "Keduanya tidak memiliki hubungan dan berjalan sendiri-sendiri."}]'::jsonb,'C','Dalam sistem negara kesatuan, perencanaan pembangunan harus berjalan secara sinergis dari pusat ke daerah. RUKN yang disusun oleh pemerintah pusat menjadi pedoman makro. Pemerintah Daerah kemudian menyusun RUKD yang merupakan penjabaran atau detail dari RUKN, disesuaikan dengan kondisi dan potensi daerahnya. Substansi RUKD tidak boleh menyimpang atau bertentangan dengan arah kebijakan yang telah ditetapkan dalam RUKN.','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kewenangan PT PLN (Persero) untuk melakukan pemadaman listrik di suatu area demi alasan keselamatan atau pemeliharaan jaringan merupakan contoh dari...','[{"key": "A", "text": "Tindakan Wanprestasi"}, {"key": "B", "text": "Perbuatan Melawan Hukum"}, {"key": "C", "text": "Pelaksanaan kewajiban pelayanan publik yang diatur undang-undang."}, {"key": "D", "text": "Tindakan sewenang-wenang."}]'::jsonb,'C','UU Ketenagalistrikan memberikan hak kepada pemegang izin usaha (PLN) untuk melakukan tindakan-tindakan tertentu demi menjamin keamanan dan keandalan pasokan listrik, termasuk melakukan pemadaman terencana untuk pemeliharaan atau pemadaman darurat untuk keselamatan. Selama dilakukan sesuai prosedur dan standar yang berlaku, tindakan ini merupakan bagian dari pelaksanaan kewajiban pelayanan publik, bukan wanprestasi.','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Pejabat/Badan Usaha Milik Negara seperti PLN dapat menjadi objek gugatan di Peradilan Tata Usaha Negara (PTUN) karena...','[{"key": "A", "text": "PLN menggunakan modal yang berasal dari negara."}, {"key": "B", "text": "PLN menjalankan sebagian fungsi pemerintahan (public function) dalam menyediakan layanan publik."}, {"key": "C", "text": "Semua karyawan PLN berstatus sebagai Pegawai Negeri Sipil."}, {"key": "D", "text": "PLN tidak dapat digugat di peradilan perdata."}]'::jsonb,'B','Meskipun berstatus badan hukum privat (Persero), BUMN seperti PLN dapat menjadi subjek hukum administrasi negara karena ia menjalankan fungsi publik yang dilimpahkan oleh negara. Dalam menjalankan fungsi penyediaan listrik inilah PLN dapat mengeluarkan keputusan-keputusan (KTUN) yang dapat merugikan hak warga negara, sehingga memberikan dasar bagi warga negara untuk menggugatnya di PTUN.','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Jika seorang pelanggan merasa dirugikan karena kesalahan pencatatan meter oleh petugas PLN yang mengakibatkan tagihan melonjak, langkah penyelesaian sengketa pertama yang paling tepat adalah...','[{"key": "A", "text": "Langsung mengajukan gugatan ke pengadilan negeri."}, {"key": "B", "text": "Melaporkan petugas ke pihak kepolisian."}, {"key": "C", "text": "Mengajukan keluhan dan meminta koreksi kepada layanan pelanggan PLN."}, {"key": "D", "text": "Mempublikasikan keluhan di media sosial."}]'::jsonb,'C','Mekanisme penyelesaian sengketa konsumen umumnya menganut prinsip penyelesaian secara internal terlebih dahulu. Langkah pertama yang paling efektif dan efisien adalah dengan menyampaikan keluhan langsung kepada penyedia jasa, dalam hal ini PLN, melalui kanal-kanal resmi yang disediakan. Hal ini memberikan kesempatan bagi PLN untuk melakukan verifikasi dan koreksi internal sebelum sengketa berlanjut ke jalur hukum atau mediasi eksternal.','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Prinsip bahwa setiap tindakan badan/pejabat pemerintahan harus memiliki dasar kewenangan yang diberikan oleh peraturan perundang-undangan disebut...','[{"key": "A", "text": "Prinsip Demokrasi"}, {"key": "B", "text": "Prinsip Negara Kesejahteraan"}, {"key": "C", "text": "Prinsip Legalitas"}, {"key": "D", "text": "Prinsip Efisiensi"}]'::jsonb,'C','Prinsip Legalitas adalah salah satu pilar utama negara hukum (rechtstaat). Prinsip ini menegaskan bahwa setiap tindakan pemerintah, baik dalam bentuk pengaturan maupun keputusan, harus memiliki dasar kewenangan yang jelas yang diberikan oleh peraturan perundang-undangan (wetmatigheid van bestuur). Tanpa dasar legalitas, tindakan pemerintah tersebut dianggap tidak sah dan dapat dibatalkan.','AKDING',40);
